\documentclass[10pt]{article}
\usepackage{pgf,tikz,tkz-euclide}
\usetkzobj{all}
\usepackage{mathrsfs}
\usetikzlibrary{decorations.text}
\usetikzlibrary{arrows}
\pagestyle{empty}
\begin{document}
\begin{tikzpicture}[scale =1, rotate =-40]

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}



%here we define (without plotting) the points A, B, C, D, O
\tkzDefPoint(0,0){M}
\tkzDefPoint(6,0){N}
\tkzDefPoint(3,0){P}
\tkzDefPoint(3,1.5){Q}

% we define the intersection of the two vectors, and we call it O
\tkzInterLL(M,N)(P,Q) \tkzGetPoint{O}

% here we plot the lines through AB, CD
\tkzMarkSegments[mark=|](M,O O,N)

\tkzMarkRightAngle[color=fadedpink,fill,size=.4](N,O,Q)
\tkzDrawSegments[very thick](M,N)
\tkzDrawLines[very thick](P,Q)
\tkzDrawSegments[very thick,color = deepskyblue](M,Q Q,N)



% here we plot the points
\tkzDrawPoints[color=black,fill=black,size=2](M,N,P,Q)
%\tkzDrawPoints[color=deepskyblue,fill=deepskyblue,size=9](P,Q)
\tkzLabelPoints[above](M)
\tkzLabelPoints[above,xshift=-5](Q)
\tkzLabelPoints[below](N)
\tkzLabelPoints[below,yshift=-5](P)
%\tkzLabelPoints[above right](Q)
\tkzLabelSegment[above right](Q,N){$3x-10$}
\tkzLabelSegment[above right](Q,M){$2x-3$}

\end{tikzpicture}

\end{document}

