%\tkzDrawPoints[color=deepskyblue,fill=deepskyblue,size=9](X,Y)
\tkzLabelPoints[left](V)
\tkzLabelPoints[left](W)
\tkzLabelPoints[above left](X)
\tkzLabelPoints[above right](Y,Z)
\tkzLabelSegment[below left](X,W){$2x+4$}
\tkzLabelSegment[below left ](X,V){$4x-2$}

\end{tikzpicture}
