%\tkzDrawPoints[color=deepskyblue,fill=deepskyblue,size=9](M,N)
\tkzLabelPoints[below](K)
\tkzLabelPoints[above](L)
\tkzLabelPoints[above left](M)
\tkzLabelPoints[above right](N)
\tkzLabelPoints[above left](P)
\tkzLabelSegment[below right](M,L){$4x-6$}
\tkzLabelSegment[above right](M,K){$2x+2$}

\end{tikzpicture}


\end{document}

